#include <memory>
#include <iostream>

struct Resource { ~Resource() { std::cout << "Deleted." << std::endl; } };

int main() {
    std::auto_ptr<Resource> ap1(new Resource);
    std::cout << "ap1 is active.\n";

    // Ownership transfer (Destructive Copy)
    std::auto_ptr<Resource> ap2 = ap1; 

    // ap1 is now null and owns nothing
    if (ap1.get() == nullptr) {
        std::cout << "ap1 lost ownership.\n";
    }

    // ap2 goes out of scope and deletes the resource.
    // ap1 does nothing.
}
